SELECT id, entry_signal_id, status, average_entry_price_usdt, stop_loss_usdt, take_profit_usdt, highest_price_usdt, profit_lock_state, profit_lock_price_usdt, entry_stage, opened_at, updated_at FROM crypto_ai.wallet_managed_position WHERE symbol='EGLDUSDT' AND opened_at BETWEEN '2026-10-11 20:00:00' AND '2026-10-12 00:00:00' ORDER BY opened_at;
SELECT id, status, close_reason, entry_price, exit_price, realized_pnl, signal_id, opened_at, closed_at FROM crypto_ai.paper_position WHERE symbol='EGLDUSDT' AND opened_at BETWEEN '2026-10-11 20:00:00' AND '2026-10-12 00:00:00' ORDER BY opened_at;